+/**
+ * Parity test — B.2 write-path convergence.
+ *
+ * Both background-precompute (computeAndPersistMatches → createMatch) and
+ * session-persist (persistSessionMatches → createMatch) must write the same
+ * 21 core columns so a match renders identically regardless of which path
+ * saved it. This test drives `createMatch` with the full field set that
+ * both writers now provide after the B.2 fix, and asserts every column lands
+ * correctly in the DB row.
+ */
+
+import Database from 'better-sqlite3';
+import { runMigrations } from '@/lib/migrations/runner';
+import { allMigrations } from '@/lib/migrations/index';
+import { createMatch } from '@/lib/matching/matches-repository';
+import type { StoredMatch } from '@/lib/matching/matches-repository';
+
+function freshDb(): Database.Database {
+  const db = new Database(':memory:');
+  runMigrations(db, allMigrations);
+  return db;
+}
+
+const FULL_INPUT = {
+  cargo_id: 'cargo-email-1',
+  vessel_id: 'vessel-email-1',
+  score: 82,
+  reason: 'test reason',
+  status: 'shortlist' as const,
+  user_id: 'session-abc',
+  reason_structured: null,
+  cargo_type: 'grain',
+  load_port: 'Rotterdam',
+  discharge_port: 'Alexandria',
+  laycan_start: 1_750_000_000_000,
+  laycan_end:   1_750_600_000_000,
+  vessel_dwt: 58_000,
+  tce_usd_per_day: 14_500,
+  distance_nm: 3_200,
+  freight_rate_usd_per_mt: 28.5,
+  freight_rate_source: 'estimated',
+  vessel_name: 'M/V DEMO VESSEL',
+  cargo_ref: 'grain 50kt',
+  fit_percent: 76,
+  fit_breakdown: '{"fitPercent":76,"components":[]}',
+  cargo_item_index: 0,
+  vessel_item_index: 1,
+  worksheet_json: '{"readiness":{"verdict":"ideal"}}',
+  consumption_estimated: null,
+  ballast_distance_nm: 420,
+  breakeven_tce_usd_per_day: 8_500,
+};
+
+describe('write-paths-parity — 21 core columns', () => {
+  let db: Database.Database;
+  let row: StoredMatch;
